 if(launcher&&workspace){launcher.addEventListener('click',()=>{const opening=workspace.hidden;workspace.hidden=!opening;launcher.setAttribute('aria-expanded',String(opening));launcher.classList.toggle('lab-launched',opening);if(opening){workspace.scrollIntoView({behavior:'smooth',block:'start'});setTimeout(()=>document.getElementById('labCommandInput')?.focus(),350);}});}
